; Landscape scroll by the jet speed
; $5f00-$5f48

; Scrolls the landscape by the speed $2a: every call at +-3, every 2nd at +-2, every 4th at +-1 ($2c counts). Negative calls $5120, positive calls $50f0. When the scroll direction agrees with $60, it updates the enemy shots two more times.
landscape_scroll_step
        inc scroll_tick
        lda jet_speed_x
        beq landscape_scroll_done
        cmp #$03
        beq landscape_scroll_do
        cmp #$fd
        beq landscape_scroll_do
        cmp #$01
        beq landscape_scroll_slow
        cmp #$ff
        beq landscape_scroll_slow
        lda scroll_tick                 ; Speed +-2: every 2nd call.
        and #$01
        bne landscape_scroll_done
        beq landscape_scroll_do
landscape_scroll_slow
        lda scroll_tick                 ; Speed +-1: every 4th call.
        and #$03
        bne landscape_scroll_done
landscape_scroll_do
        lda jet_speed_x
        bpl landscape_scroll_positive
        jsr landscape_scroll_right
        lda wave_dir
        bpl landscape_scroll_done
        jsr enemy_shot_update_twice
        clc
        bcc landscape_scroll_done
landscape_scroll_positive
        jsr landscape_scroll_left
        lda wave_dir
        cmp #$01
        bne landscape_scroll_done
        jsr enemy_shot_update_twice
landscape_scroll_done
        rts
; Calls enemy_shot_update two times.
enemy_shot_update_twice
        jsr enemy_shot_update
        jsr enemy_shot_update
        rts
